class Solution:
    def rob(self, root) -> int:
        def dfs(node):
            if not node: return (0,0)
            lt,ls=dfs(node.left);rt,rs=dfs(node.right)
            take=node.val+ls+rs
            skip=max(lt,ls)+max(rt,rs)
            return take,skip
        return max(dfs(root))

class Solution {
    public int rob(TreeNode root) { int[] r=dfs(root);return Math.max(r[0],r[1]); }
    private int[] dfs(TreeNode n) {
        if(n==null)return new int[]{0,0};
        int[] l=dfs(n.left),r=dfs(n.right);
        return new int[]{n.val+l[1]+r[1],Math.max(l[0],l[1])+Math.max(r[0],r[1])};
    }
}

