class NestedIterator:
    def __init__(self, nestedList):
        self.stack=list(reversed(nestedList))
    def next(self) -> int:
        if not self.hasNext(): raise StopIteration
        return self.stack.pop().getInteger()
    def hasNext(self) -> bool:
        while self.stack:
            top=self.stack[-1]
            if top.isInteger(): return True
            self.stack.pop()
            self.stack.extend(reversed(top.getList()))
        return False

import java.util.*;
public class NestedIterator implements Iterator<Integer> {
    private final Deque<NestedInteger> stack=new ArrayDeque<>();
    public NestedIterator(List<NestedInteger> nestedList){for(int i=nestedList.size()-1;i>=0;i--)stack.push(nestedList.get(i));}
    @Override public Integer next(){if(!hasNext())throw new NoSuchElementException();return stack.pop().getInteger();}
    @Override public boolean hasNext(){
        while(!stack.isEmpty()&&!stack.peek().isInteger()){
            NestedInteger cur=stack.pop();List<NestedInteger> list=cur.getList();
            for(int i=list.size()-1;i>=0;i--)stack.push(list.get(i));
        }return !stack.isEmpty();
    }
}

