class Solution:
    def reverseString(self, s: list[str]) -> None:
        left,right=0,len(s)-1
        while left<right:
            s[left],s[right]=s[right],s[left]
            left+=1;right-=1

class Solution {
    public void reverseString(char[] s) {
        int l=0,r=s.length-1;
        while(l<r){char t=s[l];s[l]=s[r];s[r]=t;l++;r--;}
    }
}

class Solution:
    def reverseVowels(self, s: str) -> str:
        chars=list(s);vowels=set('aeiouAEIOU');l=0;r=len(chars)-1
        while l<r:
            while l<r and chars[l] not in vowels:l+=1
            while l<r and chars[r] not in vowels:r-=1
            chars[l],chars[r]=chars[r],chars[l];l+=1;r-=1
        return ''.join(chars)

class Solution {
    private boolean vowel(char c){return "aeiouAEIOU".indexOf(c)>=0;}
    public String reverseVowels(String s) {
        char[] a=s.toCharArray();int l=0,r=a.length-1;
        while(l<r){while(l<r&&!vowel(a[l]))l++;while(l<r&&!vowel(a[r]))r--;
            char t=a[l];a[l]=a[r];a[r]=t;l++;r--;}
        return new String(a);
    }
}

from collections import Counter
class Solution:
    def topKFrequent(self, nums: list[int], k: int) -> list[int]:
        counts=Counter(nums);buckets=[[] for _ in range(len(nums)+1)]
        for value,count in counts.items():buckets[count].append(value)
        out=[]
        for freq in range(len(nums),0,-1):
            for value in buckets[freq]:
                out.append(value)
                if len(out)==k:return out
        return out

import java.util.*;
class Solution {
    public int[] topKFrequent(int[] nums,int k) {
        Map<Integer,Integer> count=new HashMap<>();for(int x:nums)count.put(x,count.getOrDefault(x,0)+1);
        List<Integer>[] buckets=new List[nums.length+1];for(int x:count.keySet()){int f=count.get(x);if(buckets[f]==null)buckets[f]=new ArrayList<>();buckets[f].add(x);}
        int[] out=new int[k];int p=0;for(int f=nums.length;f>0&&p<k;f--)if(buckets[f]!=null)for(int x:buckets[f]){out[p++]=x;if(p==k)break;}return out;
    }
}

