import java.util.*;
class Solution {
    public int[] intersection(int[] nums1,int[] nums2) {
        Set<Integer> a=new HashSet<>(),b=new HashSet<>();for(int x:nums1)a.add(x);for(int x:nums2)if(a.contains(x))b.add(x);
        int[] out=new int[b.size()];int i=0;for(int x:b)out[i++]=x;return out;
    }
}

from collections import Counter
class Solution:
    def intersect(self, nums1: list[int], nums2: list[int]) -> list[int]:
        counts=Counter(nums1);out=[]
        for x in nums2:
            if counts[x]>0:out.append(x);counts[x]-=1
        return out

import java.util.*;
class Solution {
    public int[] intersect(int[] nums1,int[] nums2) {
        Map<Integer,Integer> c=new HashMap<>();for(int x:nums1)c.put(x,c.getOrDefault(x,0)+1);
        int[] tmp=new int[Math.min(nums1.length,nums2.length)];int p=0;
        for(int x:nums2){int n=c.getOrDefault(x,0);if(n>0){tmp[p++]=x;c.put(x,n-1);}}
        return Arrays.copyOf(tmp,p);
    }
}
